using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long cop, org;
    while (cin >> cop >> org) {
        if (cop == 0 || org > cop)
            continue;

        cout << ((cop - org + 1) % 2 == 0 ? "Yes" : "No");
        break;
    }

    return 0;
}

